"use strict";var Recipe=function(totalSteps,ingredients,currentAmount){function init(){initSteps();initAmounts()}var _totalSteps=totalSteps,_progressBar=$(".progress-bar"),_steps=$("#recipe-detail h3");function initSteps(){$(".steps").on("init",function(){updateStates(1)}).slick({adaptiveHeight:true,prevArrow:$("#arrows .previous"),nextArrow:$("#arrows .next"),infinite:false,pauseOnFocus:false}).on("beforeChange",function(event,slick,currentSlide,nextSlide){updateStates(nextSlide+1)})}function updateStates(step){var steps=LANG.localize("step_x_of_total");steps=steps.replace("%x",step);steps=steps.replace("%t",_totalSteps);_steps.html(steps);_progressBar.css("width",100/(_totalSteps-1)*(step-1)+"%")}var _ingredients=ingredients,_currentAmount=currentAmount,_amount=$("#amount");function initAmounts(){$("#add, #subtract").click(function(e){var amount=parseFloat(_amount.val());if(amount%1===0){if($(this).attr("id")==="add")amount++;else amount--}else{if($(this).attr("id")==="add")amount=Math.ceil(amount);else amount=Math.floor(amount)}amountChanged(amount);e.preventDefault();return false});_amount.change(function(){var amount=parseFloat(_amount.val());amountChanged(amount)})}function amountChanged(amount){if(amount<=0)amount=1;_amount.val(amount);$("span.diners").html(amount);for(var i in _ingredients){$("span.ingredient-"+_ingredients[i]["uri"]).each(function(){var unit=$(this).attr("data-unit"),unitPlural=$(this).attr("data-plural"),unitary=$(this).attr("data-unitary")==="1",fraction=parseFloat($(this).attr("data-fraction")),totalAmount=_ingredients[i]["amount"]/_currentAmount*amount;if(!isNaN(fraction)){totalAmount=Math.ceil(totalAmount*fraction)}totalAmount=Math.round(totalAmount*10)/10;if(unitary){totalAmount=Math.round(totalAmount)}if(totalAmount!==1){totalAmount+=" "+unitPlural}else{totalAmount+=" "+unit}$(this).html(totalAmount)})}}init()};